const MARKER = "MS_CONNECTION_ERROR_KV_V1";
const RESPONSIVE_MARKER = "MS_CONNECTION_RESPONSIVE_V2";
const OBSERVER_URL = "https://waiting-trucks-ms-browser-test.26nak-testdev.workers.dev/api/connection-error";

function replaceUnique(source, from, to, label) {
  const first = source.indexOf(from);
  const last = source.lastIndexOf(from);
  if (first < 0 || first !== last)
    throw new Error(`MS connection Browser KV patch failed: ${label}`);
  return source.replace(from, to);
}

export function patchMsConnectionErrorKvFrontend(source) {
  let output = String(source || "");
  if (output.includes(MARKER)) return output;

  const helperAnchor = `document.addEventListener("DOMContentLoaded", () => {`;
  const helpers = [
    `// ${MARKER}: persist only HAR/MS error metadata in Browser Worker KV; never Turso or LocalStorage.`,
    `const MS_CONNECTION_OBSERVER_URL = "${OBSERVER_URL}";`,
    `const MS_CONNECTION_RESPONSIVE_MARKER = "${RESPONSIVE_MARKER}";`,
    ``,
    `function msConnectionSourceLabel(source) {`,
    `  if (source === "routes") return "บันทึกสถานะเส้นทางเดินรถ";`,
    `  if (source === "preEntry") return "พัสดุที่คาดว่าจะเข้าคลัง";`,
    `  if (source === "busTime") return "การจัดการตารางเวลา KIT/TBR";`,
    `  if (source === "originManifest") return "LH Manifest พัสดุออกจริง / น้ำหนัก";`,
    `  return "การเชื่อมต่อ MS";`,
    `}`,
    ``,
    `function msConnectionObserverBox() {`,
    `  const anchor = el("ms-connection-error");`,
    `  if (!anchor) return null;`,
    `  let box = el("ms-connection-last-error");`,
    `  if (!box) {`,
    `    box = document.createElement("div");`,
    `    box.id = "ms-connection-last-error";`,
    `    box.className = "hidden";`,
    `    box.setAttribute("aria-live", "polite");`,
    `    box.style.marginTop = "10px";`,
    `    box.style.padding = "10px 12px";`,
    `    box.style.border = "1px solid rgba(0,0,0,.12)";`,
    `    box.style.borderRadius = "10px";`,
    `    box.style.fontSize = "13px";`,
    `    box.style.lineHeight = "1.5";`,
    `    box.style.background = "rgba(0,0,0,.035)";`,
    `    anchor.insertAdjacentElement("afterend", box);`,
    `  }`,
    `  return box;`,
    `}`,
    ``,
    `function renderMsConnectionObservedError(record) {`,
    `  const box = msConnectionObserverBox();`,
    `  if (!box) return;`,
    `  if (!record) {`,
    `    box.classList.add("hidden");`,
    `    box.replaceChildren();`,
    `    return;`,
    `  }`,
    `  box.classList.remove("hidden");`,
    `  box.replaceChildren();`,
    `  const title = document.createElement("strong");`,
    `  title.textContent = "ข้อผิดพลาดการเชื่อมต่อล่าสุด";`,
    `  const detail = document.createElement("div");`,
    `  const occurred = record.occurredAt ? shortDateTime(record.occurredAt) : "-";`,
    `  detail.textContent = (record.hub || "-") + " · " + msConnectionSourceLabel(record.source) + " · " + (record.code || "ERROR") + " · " + (record.label || "") + " · " + occurred;`,
    `  const message = document.createElement("div");`,
    `  message.textContent = String(record.message || "");`,
    `  message.style.opacity = ".78";`,
    `  box.append(title, detail, message);`,
    `  if (record.recoveredAt) {`,
    `    const recovered = document.createElement("div");`,
    `    recovered.textContent = "✓ เชื่อมต่อสำเร็จอีกครั้ง " + shortDateTime(record.recoveredAt) + " · error นี้ถูกแก้แล้ว";`,
    `    recovered.style.marginTop = "4px";`,
    `    recovered.style.fontWeight = "700";`,
    `    box.append(recovered);`,
    `  }`,
    `}`,
    ``,
    `function installMsConnectionResponsiveV2(attempt = 0) {`,
    `  const details = document.querySelector("#ms-connection-form details.setup-fallback");`,
    `  const list = details?.querySelector(".har-source-list");`,
    `  const statusBox = document.getElementById("connection-source-status");`,
    `  const manifestInput = document.getElementById("ms-har-origin-manifest");`,
    `  if (!details || !list || !statusBox || !manifestInput) {`,
    `    if (attempt < 20) setTimeout(() => installMsConnectionResponsiveV2(attempt + 1), 50);`,
    `    return;`,
    `  }`,
    ``,
    `  let style = document.getElementById("ms-connection-responsive-v2-style");`,
    `  if (!style) {`,
    `    style = document.createElement("style");`,
    `    style.id = "ms-connection-responsive-v2-style";`,
    `    style.textContent = ".connector-dialog{width:min(96vw,980px);max-height:calc(100dvh - 24px)}.connector-dialog .connector-setup-card{max-width:none}.connection-source-status.ms-source-status-v2{grid-template-columns:1fr;align-items:stretch}.connection-source-status.ms-source-status-v2>div{min-width:0;align-items:flex-start;flex-direction:column}.connection-source-status.ms-source-status-v2 span{text-align:left}.setup-source-links.ms-source-links-v2{display:grid;grid-template-columns:1fr;gap:8px}.setup-source-links.ms-source-links-v2 .setup-link{width:100%;margin:0;justify-content:center;text-align:center;white-space:normal}.har-source-list.ms-har-cards-v2{display:grid;grid-template-columns:1fr;gap:12px;margin-top:14px;align-items:stretch}.har-source-card-v2{min-width:0;display:flex;flex-direction:column;gap:9px;padding:13px;border:1px solid #d8d8d4;border-radius:10px;background:#fbfbf8}.har-source-card-v2 label{display:grid!important;gap:7px!important;margin:0!important;font-size:13px!important;line-height:1.4}.har-source-card-v2 label>span{min-height:0;font-weight:800;color:#252525}.har-source-card-v2 input[type=file]{width:100%;min-height:42px;padding:7px;border:1px solid #c9ccc8;border-radius:7px;background:#fff}.har-source-card-v2 .btn{width:100%;min-height:44px;margin-top:auto;white-space:normal}.har-source-card-v2 small{display:block;color:#656b66;font-size:11px;line-height:1.45}.hbi-sso-note-v2{margin:13px 0 0;padding:12px 14px;border:1px solid #e0bd31;border-left:4px solid #ffd400;border-radius:8px;background:#fff9db;color:#453900;line-height:1.5}.hbi-sso-note-v2 strong,.hbi-sso-note-v2 span{display:block}.hbi-sso-note-v2 span{margin-top:3px;font-size:12px}.setup-fallback>summary{padding:8px 0;font-weight:900}.connector-dialog .setup-warning{margin-top:14px}@media(max-width:760px){.connector-dialog{width:calc(100vw - 12px);max-height:calc(100dvh - 12px)}.connector-dialog .dialog-card{padding:18px 13px}.har-source-card-v2 label>span{min-height:0}.setup-steps{padding-left:20px}.hbi-sso-note-v2{padding:11px 12px}}@media(max-width:420px){.connector-dialog{width:calc(100vw - 6px);max-height:calc(100dvh - 6px)}.connector-dialog .dialog-card{padding:16px 10px}.har-source-card-v2{padding:11px}.har-source-card-v2 input[type=file]{font-size:12px}.connection-source-status>div{padding:10px 11px}}";`,
    `    document.head.appendChild(style);`,
    `  }`,
    ``,
    `  const summary = details.querySelector("summary");`,
    `  if (summary) summary.textContent = "อัปโหลด HAR ทั้ง 6 แหล่ง";`,
    `  for (const node of details.querySelectorAll(".setup-steps span")) {`,
    `    if (/ทั้ง [45] หน้าด้านล่าง/.test(node.textContent)) node.textContent = node.textContent.replace(/ทั้ง [45] หน้าด้านล่าง/, "ทั้ง 6 หน้าด้านล่าง");`,
    `  }`,
    ``,
    `  const proofStatus = statusBox.querySelector('[data-source-status="proof"] b');`,
    `  if (proofStatus) proofStatus.textContent = "5. ปริ้นบาร์โค้ดรถ";`,
    `  const manifestStatus = statusBox.querySelector('[data-source-status="originManifest"] b');`,
    `  if (manifestStatus) manifestStatus.textContent = "6. LH Manifest (พัสดุออกจริง / น้ำหนัก Kg)";`,
    `  statusBox.classList.add("ms-source-status-v2");`,
    ``,
    `  const links = details.querySelector(".setup-source-links");`,
    `  if (links) {`,
    `    links.classList.add("ms-source-links-v2");`,
    `    const manifestLink = [...links.querySelectorAll("a")].find((item) => String(item.href || "").includes("hbi-v3.flashexpress.com/lh-manifest"));`,
    `    if (manifestLink) {`,
    `      manifestLink.textContent = "6. เปิด LH Manifest (หลังเข้า HBI SSO)";`,
    `      manifestLink.title = "ถ้าขึ้น NEED_LOGIN ให้เข้า HBI ผ่าน FlashGroup/BI ก่อน แล้วค่อยเปิด LH Manifest";`,
    `    }`,
    `  }`,
    ``,
    `  const proofLabel = list.querySelector('[data-dev-proof-har="DEV_PROOF_HAR_CONNECTION_V9"] > span');`,
    `  if (proofLabel) proofLabel.textContent = "5. HAR ปริ้นบาร์โค้ดรถ";`,
    `  const manifestLabel = manifestInput.closest("label")?.querySelector("span");`,
    `  if (manifestLabel) manifestLabel.textContent = "6. HAR LH Manifest · พัสดุออกจริง + น้ำหนัก Kg";`,
    ``,
    `  if (!document.getElementById("hbi-sso-note-v2")) {`,
    `    const note = document.createElement("div");`,
    `    note.id = "hbi-sso-note-v2";`,
    `    note.className = "hbi-sso-note-v2";`,
    `    note.innerHTML = "<strong>LH Manifest ใช้ HBI SSO แยกจากการล็อกอินหน้า MS</strong><span>ถ้าเปิดแล้วเห็น NEED_LOGIN ไม่ได้แปลว่า MS หลุด แต่หมายถึง HBI ยังไม่ได้รับ SSO ticket ให้เปิด HBI ผ่านเมนู FlashGroup / BI ที่ใช้งานตามปกติจนเข้า LH Manifest ได้ แล้วจึง Export HAR</span>";`,
    `    list.insertAdjacentElement("beforebegin", note);`,
    `  }`,
    ``,
    `  if (!list.classList.contains("ms-har-cards-v2")) {`,
    `    const children = [...list.children];`,
    `    const fragment = document.createDocumentFragment();`,
    `    let card = null;`,
    `    for (const child of children) {`,
    `      if (child.tagName === "LABEL") {`,
    `        card = document.createElement("div");`,
    `        card.className = "har-source-card-v2";`,
    `        fragment.appendChild(card);`,
    `      }`,
    `      if (card) card.appendChild(child);`,
    `      else fragment.appendChild(child);`,
    `    }`,
    `    list.replaceChildren(fragment);`,
    `    list.classList.add("ms-har-cards-v2");`,
    `  }`,
    `  details.dataset.connectionResponsive = MS_CONNECTION_RESPONSIVE_MARKER;`,
    `}`,
    ``,
    `document.addEventListener("DOMContentLoaded", () => setTimeout(() => installMsConnectionResponsiveV2(), 0), { once: true });`,
    `document.addEventListener("click", (event) => {`,
    `  if (event.target.closest("#ms-connection-btn")) setTimeout(() => installMsConnectionResponsiveV2(), 0);`,
    `});`,
    ``,
    `async function loadMsConnectionObservedError(hubValue) {`,
    `  const hub = String(hubValue || "").trim().toUpperCase();`,
    `  if (!hub) return;`,
    `  try {`,
    `    const url = new URL(MS_CONNECTION_OBSERVER_URL);`,
    `    url.searchParams.set("hub", hub);`,
    `    const response = await fetch(url, { cache: "no-store", headers: { Accept: "application/json" } });`,
    `    const json = await response.json().catch(() => ({}));`,
    `    if (response.ok && json?.ok !== false) renderMsConnectionObservedError(json?.data || null);`,
    `  } catch {}`,
    `}`,
    ``,
    `async function reportMsConnectionObservation(event, source, hubValue, error = null) {`,
    `  const hub = String(hubValue || "").trim().toUpperCase();`,
    `  if (!hub) return;`,
    `  const message = String(error?.message || "").slice(0, 240);`,
    `  const rawCode = String(error?.code || "").slice(0, 40);`,
    `  const code = /429|rate.?limit|too many requests/i.test(rawCode + " " + message) ? "429" : rawCode || "ERROR";`,
    `  try {`,
    `    const url = new URL(MS_CONNECTION_OBSERVER_URL);`,
    `    url.searchParams.set("hub", hub);`,
    `    await fetch(url, {`,
    `      method: "POST",`,
    `      headers: { "content-type": "application/json" },`,
    `      body: JSON.stringify({ event, source, code, message }),`,
    `      cache: "no-store",`,
    `      keepalive: true,`,
    `    });`,
    `  } catch {}`,
    `}`,
    ``,
  ].join("\n");

  output = replaceUnique(
    output,
    helperAnchor,
    helpers + helperAnchor,
    "insert Browser KV connection helpers",
  );

  output = replaceUnique(
    output,
    `  el("ms-connection-dialog").showModal();\n  loadMsConnectionStatus();\n}`,
    `  el("ms-connection-dialog").showModal();\n  loadMsConnectionStatus();\n  void loadMsConnectionObservedError(hubInput.value);\n}`,
    "load last Browser KV error when connector dialog opens",
  );

  output = replaceUnique(
    output,
    `      const result = await apiPost("saveMsPreEntryConnection", { hub, credentials });\n      errorEl.classList.add("hidden");`,
    `      const result = await apiPost("saveMsPreEntryConnection", { hub, credentials });\n      void reportMsConnectionObservation("recovered", source, hub).then(() => loadMsConnectionObservedError(hub));\n      errorEl.classList.add("hidden");`,
    "mark pre-entry recovery",
  );

  output = replaceUnique(
    output,
    `      const result = await apiPost("saveMsBusConnection", { hub, credentials });\n      errorEl.classList.add("hidden");`,
    `      const result = await apiPost("saveMsBusConnection", { hub, credentials });\n      void reportMsConnectionObservation("recovered", source, hub).then(() => loadMsConnectionObservedError(hub));\n      errorEl.classList.add("hidden");`,
    "mark BusTime recovery",
  );

  output = replaceUnique(
    output,
    `    const result = await apiPost("saveMsConnection", {\n      hub,\n      sessionId,\n      deviceId,\n    });\n    errorEl.classList.add("hidden");`,
    `    const result = await apiPost("saveMsConnection", {\n      hub,\n      sessionId,\n      deviceId,\n    });\n    void reportMsConnectionObservation("recovered", source, hub).then(() => loadMsConnectionObservedError(hub));\n    errorEl.classList.add("hidden");`,
    "mark route HAR recovery",
  );

  output = replaceUnique(
    output,
    `  } catch (error) {\n    errorEl.textContent = error.message;\n    errorEl.classList.remove("hidden");\n  } finally {\n    button.disabled = false;\n  }\n}\n\nfunction exportCurrent() {`,
    `  } catch (error) {\n    void reportMsConnectionObservation("error", source, hub, error).then(() => loadMsConnectionObservedError(hub));\n    errorEl.textContent = error.message;\n    errorEl.classList.remove("hidden");\n  } finally {\n    button.disabled = false;\n  }\n}\n\nfunction exportCurrent() {`,
    "remember HAR/MS error in Browser KV",
  );

  return output;
}